import Foundation

struct FestivalSeed: Codable, Hashable, Identifiable {
    let id: String
    let name: String
    let dateString: String
    let emoji: String
    let tier: Int
    let hint: String
    let tags: [String]

    var date: Date? {
        let p = dateString.split(separator: "-").compactMap { Int($0) }
        guard p.count == 3 else { return nil }
        var c = DateComponents()
        c.calendar = Calendar(identifier: .gregorian)
        c.timeZone = TimeZone(identifier: "Asia/Shanghai")
        c.year = p[0]; c.month = p[1]; c.day = p[2]; c.hour = 0
        return c.date
    }
}

